"""Predefine strong output-only frontier and full online cohort, using Train only."""
import json,hashlib,sys,datetime,math
from pathlib import Path
import numpy as np
R=Path('/root/autodl-tmp/ouro-e7');E=Path('/root/autodl-tmp/ouro-e6a');sys.path.insert(0,str(E/'E6A'))
from E6A_METHODS import infer,fixed_specs,calibration_grid
rows=[json.loads(l) for l in (E/'next_step_train_diagnosis/TRAIN_ONLY_INPUTS.jsonl').read_text().splitlines()];assert len(rows)==1094 and all(q['split']=='train' for q in rows)
rules={k:v for k,v in {**fixed_specs(),**calibration_grid()}.items() if v['kind']=='early' or k=='K4'}
def select(rr):
 base=sum(q['pred'][3]==q['gold'] for q in rr);allrules=[]
 for name,spec in rules.items():
  d=[infer(q['scores'],spec) for q in rr];correct=sum(x['prediction']==q['gold'] for x,q in zip(d,rr));allrules.append({'method':name,'spec':spec,'n_training_questions':len(rr),'correct':correct,'native_K4_correct':base,'mean_replay_loops':float(np.mean([x['executed_loops'] for x in d])),'feasible':(correct-base)/len(rr)>=-.005})
 chosen=sorted([x for x in allrules if x['feasible']],key=lambda x:(x['mean_replay_loops'],-x['correct'],x['method']))[0]
 return {'chosen':chosen,'all_fixed_candidates':allrules}
out={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'PROTOCOL_ONLY_NOT_ONLINE_RESULTS','launch_gate':'G1 prospective candidate combined paired Brier improvement CI lower>0 vs output, low-layer, shuffle; all three required','cohort':'All1094 Train question-disjoint OOF models, then all299 Validation with Train-only final model; no chosen subsample, no Test','policies':['native_K4','supervised_output_only','supervised_H2_candidate','predeclared_early_output_frontier'],'actions':{'supervised_prospective':'AtK2/K3 predicted utility2 or3->stop;elsecontinue to4','supervised_retrospective':'At completedK4 class2->K3 elseK4; optional separate fixed-budget branch, never early exit'},'permission':'Supervised head separate from original no-new-training/label-calibrated E6 rules. No gold at inference.','frontier_rule':'8 predeclared rules (K4 plus7 early policies); choose smallest meanloops among training accuracy no more than0.5pp below trainingK4; thenhighercorrect/name ties. Selection per outer-training fold only; one final fullTrain choice for Val. Classified Cal, not ZL.','fold_output_frontiers':{str(f):select([q for q in rows if q['outer_fold']!=f]) for f in range(5)},'validation_output_frontier':select(rows),'timing':'Actual physical depth, extra heads/hooks/featureCPU/inference/controller/synchronization included; model loading separate; alternating policy order, firstcold retained and separately summarized; no subtraction of extra overhead','numeric_QA':'selected native fullvocab endpoint hash and H2 prefixfeatures vs capture; parameter versions unchanged','G2_success':{'accuracy':'paired95 accuracy lower>0 vs K4 and strongest output under actual matchedbudget','efficiency':'observed accuracy>=strong output; paired95 difference lower>=−0.5pp and actualmeanlatency at least10%lower; not called accuracy improvement'},'weights_modified':False,'source_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'original_folds_sha256':hashlib.sha256((E/'next_step_train_diagnosis/FOLD_MANIFEST.json').read_bytes()).hexdigest()}
p=R/'H2_ONLINE_PROTOCOL.json';assert not p.exists();p.write_text(json.dumps(out,indent=2));print('H2_ONLINE_PROTOCOL_FROZEN',{k:v['chosen']['method'] for k,v in out['fold_output_frontiers'].items()},flush=True)
